#pragma once
// Frame-based image/animation playback into the 8-bit RGB332 framebuffer.
// Assets are generated by scripts/asset_convert.py (see assets_gen.h).
#include <stdint.h>

struct AnimFrame {
  const uint8_t* rle;  // 0x00-3F literal n+1, 0x40-7F repeat n+1, 0x80-FF skip n+1
  uint16_t ms;
};
struct AnimTag {
  const char* name;
  uint16_t from, to;  // inclusive frame range
};
struct AnimAsset {
  int16_t x, y;  // trimmed frame offset within the source canvas
  uint16_t w, h;
  uint16_t frameCount;
  const AnimFrame* frames;
  uint8_t tagCount;
  const AnimTag* tags;
};
struct AnimRect {
  int16_t x, y;
  uint8_t w, h, c;
};
struct AnimRectSet {
  uint16_t count;
  const AnimRect* rects;
};

// Target buffer: row-major RGB332, `w` x `h` pixels.
struct Canvas8 {
  uint8_t* px;
  int w, h;
  void fill(int x, int y, int fw, int fh, uint8_t c) const;
  void put(int x, int y, uint8_t c) const {
    if ((unsigned)x < (unsigned)w && (unsigned)y < (unsigned)h) px[y * w + x] = c;
  }
};

// Frame shown `ms` into a looping playback of `tag` (nullptr: all frames).
uint16_t animFrameAt(const AnimAsset& a, uint32_t ms, const char* tag = nullptr);

// Draws a frame with the source canvas origin at (x, y). Transparent pixels
// are skipped; output is clipped to the canvas.
void animBlit(const Canvas8& c, const AnimAsset& a, uint16_t frame, int x, int y,
              uint8_t scale = 1, bool flipX = false);
